script:
.hover-card {
    position: relative;
    overflow: hidden;
    z-index: 1;
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.hover-card::before {
    content: "";
    position: absolute;
    inset: 0;                      /* top/left/right/bottom: 0 */
    background: #011E41;
    transform: scaleX(0);
    transform-origin: right;       /* un-hover: collapses toward the right */
    transition: transform 0.6s ease;
    z-index: -1;
}

.hover-card:hover::before {
    transform: scaleX(1);
    transform-origin: left;        /* hover: expands from the left */
}

.hover-card:hover {
    transform: translateY(-8px);
    box-shadow: 0 12px 24px rgba(0, 0, 0, 0.15);
}

.hover-card:hover .hovert {
    color: white !important;
}
